/* PixelProof — accessible, dependency-light ES6+ interface engineering showcase.
 * The core app uses native DOM APIs so employers can inspect the fundamentals.
 * The pricing component in react-lab.js uses actual React; search uses jQuery AJAX.
 */
(() => {
  'use strict';
  const root = document.querySelector('#app');
  const routes = ['home','store','studio','lab','quality','admin','checkout','confirmation'];
  const CATEGORIES = ['All','Lighting','Audio','Furniture','Accessories','Lifestyle'];
  const icons = {
    arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
    bag:'<path d="M4 8h16l-1 13H5L4 8Zm4 0V6a4 4 0 0 1 8 0v2"/>',
    search:'<circle cx="11" cy="11" r="7"/><path d="m20 20-4-4"/>',
    code:'<path d="m8 5-6 7 6 7m8-14 6 7-6 7m-3-17-3 20"/>',
    eye:'<path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
    layers:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M9 3v18"/>',
    chart:'<path d="M3 3v18h18m-15-4 5-5 4 2 5-8"/>',
    shield:'<path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10Z"/><path d="m9 12 2 2 4-4"/>',
    monitor:'<rect x="2" y="3" width="20" height="15" rx="2"/><path d="M8 22h8m-4-4v4"/>',
    mobile:'<rect x="6" y="2" width="12" height="20" rx="2"/><path d="M11 18h2"/>',
    tablet:'<rect x="4" y="2" width="16" height="20" rx="2"/><path d="M11 18h2"/>',
    check:'<path d="m5 12 5 5L20 7"/>',
    close:'<path d="M18 6 6 18M6 6l12 12"/>',
    plus:'<path d="M12 5v14m-7-7h14"/>',
    menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
    terminal:'<rect x="2" y="3" width="20" height="18" rx="2"/><path d="m6 9 3 3-3 3m6 0h5"/>',
    copy:'<rect x="8" y="8" width="12" height="12" rx="2"/><path d="M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2"/>',
    refresh:'<path d="M3 12a9 9 0 0 1 15-7l3 3m0-5v5h-5M21 12a9 9 0 0 1-15 7l-3-3m0 5v-5h5"/>',
    sliders:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2" fill="white"/><circle cx="16" cy="12" r="2" fill="white"/>',
    box:'<rect x="3" y="3" width="18" height="18" rx="3"/><path d="M3 9h18M9 9v12"/>',
    clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
  };
  const icon = (name, size=17) => `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]||icons.box}</svg>`;
  const safe = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const money = amount => new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(amount);
  const loadCart = () => {try {const v=JSON.parse(localStorage.getItem('pixelproof-cart')||'{}');return v&&typeof v==='object'&&!Array.isArray(v)?v:{};}catch{return {};}};
  const state = {
    route:'home',mobileNav:false,products:[],catalog:[],catalogLoaded:false,isLoading:false,category:'All',sort:'featured',query:'',cart:loadCart(),overlay:null,
    studio:{accent:'#45634c',radius:16,spacing:24,device:'desktop',grid:false},
    qualityResults:null,qualityRunning:false,qualityElapsed:null,lastOrder:null,
  };
  let searchTimer,storeAbort,jqXHR,focusReturn=null,catalogPromise=null;
  const cartCount = () => Object.values(state.cart).reduce((sum,n)=>sum+Number(n||0),0);
  const storeCart = () => {try{localStorage.setItem('pixelproof-cart',JSON.stringify(state.cart));}catch{}};
  const toast = (message,error=false) => {
    const node = document.createElement('div');node.className=`toast-message${error?' error':''}`;node.textContent=message;
    document.querySelector('#toast-region').appendChild(node);setTimeout(()=>node.remove(),3300);
  };
  const navNames = [['home','Overview'],['store','Storefront'],['studio','Design studio'],['lab','Interaction lab'],['quality','Quality bench'],['admin','Admin login']];
  function header() {return `<header class="site-header"><div class="container-app header-inner">
      <a class="brand" href="#/home" aria-label="PixelProof home"><span class="brand-icon">P<b>.</b></span><span><span class="brand-name">pixelproof.</span><span class="brand-sub">INTERFACE ENGINEERING LAB</span></span></a>
      <nav class="nav-wrap${state.mobileNav?' open':''}" aria-label="Main navigation">${navNames.map(([r,label])=>`<a class="nav-link${state.route===r?' active':''}" href="#/${r}" ${state.route===r?'aria-current="page"':''}>${label}</a>`).join('')}</nav>
      <div class="header-actions"><span class="header-status"><span class="online-dot"></span> Live & interactive</span><button class="icon-btn" data-action="cart" aria-label="Open shopping cart">${icon('bag',17)} <span class="count-bubble">${cartCount()}</span></button><button class="icon-btn menu-toggle" data-action="menu" aria-label="Toggle navigation" aria-expanded="${state.mobileNav}">${icon('menu')}</button></div>
    </div></header>`;}
  function footer(){return `<footer class="container-app footer"><div><strong>pixelproof.</strong> &nbsp; Built to the pixel. Proven in the browser.</div><div class="footer-links"><button data-action="navigate" data-route="quality">Test the app</button><button data-action="navigate" data-route="studio">Inspect CSS</button><a href="https://github.com/sachintechpro" target="_blank" rel="noopener noreferrer">GitHub profile ↗</a><span>HTML · CSS · JS · React · jQuery · API</span></div></footer>`;}
  function pageHead(kicker,title,lead,aside=''){return `<div class="page-header"><span class="eyebrow"><span class="mini-dot"></span>${kicker}</span><div style="display:flex;justify-content:space-between;gap:20px;align-items:end;flex-wrap:wrap"><div><h1 style="margin:12px 0 15px">${title}</h1><p class="large-lead" style="margin:0">${lead}</p></div>${aside}</div></div>`;}
  const demos = [
    {id:'store',num:'01',title:'The storefront',label:'COMMERCE ENGINEERING',desc:'A complete shopping flow with live catalog APIs, filtering, sorting, cart persistence, and validated checkout.',tech:['HTML5 / CSS3','JavaScript','REST API','Responsive']},
    {id:'studio',num:'02',title:'The design studio',label:'PIXEL PRECISION',desc:'Adjust design tokens, inspect CSS output, overlay layout guides, and preview responsive device widths.',tech:['CSS Grid','Media queries','Design systems','DevTools']},
    {id:'lab',num:'03',title:'The interaction lab',label:'CLIENT-SIDE DEVELOPMENT',desc:'Working jQuery AJAX, debounced search, form validation, accessible components, and a React configurator.',tech:['ES6+','jQuery','React','Bootstrap']},
    {id:'quality',num:'04',title:'The quality bench',label:'BROWSER & API VALIDATION',desc:'Run real in-browser checks for API health, response handling, images, responsive state, and accessibility basics.',tech:['API debugging','Cross-browser','Performance','Testing']},
    {id:'admin',num:'05',title:'Commerce command',label:'END-TO-END OPERATIONS',desc:'Run a connected back-office console: create products, update inventory, process sample orders, and verify storefront updates.',tech:['CRUD API','Inventory','Order fulfillment','ES6+']},
  ];
  function demoPreview(d) {
    if(d.id==='store') return `<div style="display:flex;align-items:center;gap:12px"><img src="/assets/lamp.svg" alt="" loading="lazy"><div style="background:#fff;border-radius:9px;padding:12px;box-shadow:0 6px 26px #0001;font-size:10px;font-weight:800;white-space:nowrap">✓ Added to bag<br><span style="color:#a0aca1">Arc desk lamp</span></div></div>`;
    if(d.id==='studio')return `<div class="mock-window"><div class="mock-window-bar"><i></i><i></i><i></i></div><div style="display:flex;padding:14px;gap:15px"><div style="width:50%"><div style="background:#364d3c;width:63px;height:7px;border-radius:5px;margin-bottom:25px"></div><div style="background:#4a5f50;width:92%;height:10px;border-radius:5px;margin-bottom:8px"></div><div style="background:#4a5f50;width:72%;height:10px;border-radius:5px;margin-bottom:17px"></div><div style="background:#b6d891;width:72px;height:22px;border-radius:5px"></div></div><div style="background:#e3e5df;width:50%;border-radius:8px;overflow:hidden"><img src="/assets/chair.svg" style="width:100%;height:132px;object-fit:cover" alt="" loading="lazy"></div></div></div>`;
    if(d.id==='lab')return `<div class="mock-window"><div class="mock-window-bar"><i></i><i></i><i></i></div><div style="padding:16px"><div style="font-weight:800;font-size:12px;margin-bottom:12px">Component playground</div><div style="height:26px;border-radius:6px;background:#eef2f4;border:1px solid #d9e2e5;margin-bottom:9px;padding:6px 11px;font-size:9px;color:#89949b">Search components...</div><div style="padding:8px 11px;background:#e8f1ed;border-radius:6px;font-size:9px;margin-bottom:5px">⌘ &nbsp; Dynamic result one &nbsp; &nbsp; ✓</div><div style="padding:8px 11px;background:#edf2ee;border-radius:6px;font-size:9px">⌘ &nbsp; Dynamic result two &nbsp; &nbsp; ✓</div></div></div>`;
    if(d.id==='admin')return `<div class="mock-window"><div class="mock-window-bar"><i></i><i></i><i></i></div><div style="padding:16px"><div style="font-weight:800;font-size:12px;margin-bottom:12px">Commerce operations <span style="color:#5e855b">● Live</span></div><div style="display:flex;gap:9px;margin-bottom:12px">${['$598','03 orders','02 alerts'].map(t=>`<div style="background:#f1f6ee;border-radius:7px;padding:8px;font-size:10px;font-weight:800">${t}</div>`).join('')}</div><div style="font-size:10px;border-bottom:1px solid #e5e9df;padding:6px 0">▣ &nbsp; Arc desk lamp &nbsp; · &nbsp; 12 in stock</div><div style="font-size:10px;padding:6px 0">▣ &nbsp; Form keyboard &nbsp; · &nbsp; 19 in stock</div></div></div>`;
    return `<div class="mock-window"><div class="mock-window-bar"><i></i><i></i><i></i></div><div style="padding:14px"><div style="font-size:10px;font-weight:800;margin-bottom:10px">Browser checks <span style="color:#5f9651">● All passing</span></div>${['API response · 200 OK','Images · loaded','Layout · responsive'].map(s=>`<div style="padding:7px 0;border-bottom:1px solid #e5eee6;color:#486c4d;font-size:10px">✓ &nbsp; ${s}</div>`).join('')}</div></div>`;
  }
  function home(){return `<main id="main" class="container-app page"><section class="hero"><div class="hero-grid">
    <div class="hero-main"><div><span class="eyebrow"><span class="mini-dot"></span>NOT A SLIDESHOW. A WORKING APPLICATION.</span><h1>Good interfaces<br>don't just look good.<br><em>They work.</em></h1><p>Built to the pixel. Proven in the browser. Five hands-on experiments with real interactions, APIs, and inspectable code.</p><div class="hero-cta"><button class="button light" data-action="navigate" data-route="store">Explore the storefront ${icon('arrow')}</button><button class="button" style="border:1px solid #64816b;background:transparent" data-action="navigate" data-route="quality">Run quality checks ${icon('arrow')}</button></div></div><div class="hero-foot"><span>DESIGNED IN DETAIL. BUILT WITH INTENT.</span><span>SCROLL TO EXPLORE ↓</span></div></div>
    <div class="hero-aside"><div><span class="overline">FEATURED EXPERIMENT / 01</span><h3>An everyday object.<br>An extraordinary level<br>of detail.</h3></div><img src="/assets/lamp.svg" alt="Illustrated sculptural desk lamp from the storefront demo"><div class="floating-label"><small>LIVE SHOPPING DEMO</small>Products · Cart · Checkout</div></div></div></section>
    <section class="proof-strip" aria-label="Portfolio highlights"><div class="proof-stat"><strong>05</strong><span>LIVE EXPERIMENTS</span></div><div class="proof-stat"><strong>100%</strong><span>INTERACTIVE UI</span></div><div class="proof-stat"><strong>06</strong><span>API ENDPOINT GROUPS</span></div><div class="proof-stat"><strong>0</strong><span>BUILD DEPENDENCIES</span></div></section>
    <section><div class="section-title"><div><span class="eyebrow"><span class="mini-dot"></span>THE WORKSHOP</span><h2 style="margin-top:11px">Explore what I build.</h2><p>Every module is functional. Pick one and put it to the test.</p></div><span class="pill outline">5 PROJECT MODULES</span></div><div class="demo-grid">${demos.map(d=>`<article class="demo-card"><div class="demo-image ${d.id}">${demoPreview(d)}</div><div class="demo-card-content"><div class="demo-card-top"><span class="eyebrow">${d.label}</span><span class="pill">${d.num} / 05</span></div><h3>${d.title}</h3><p>${d.desc}</p><div class="tags">${d.tech.map(t=>`<span class="tag">${t}</span>`).join('')}</div><button class="link-row" data-action="navigate" data-route="${d.id}" style="width:100%;background:none;border:0;padding:0;text-align:left">Explore live demo <span>${icon('arrow')}</span></button></div></article>`).join('')}</div></section>
    <section class="skill-band"><div><span class="eyebrow">UNDER THE HOOD</span><h2 style="margin:12px 0">The fundamentals.<br>Without the shortcuts.</h2><p>From semantic markup to responsive layouts, real API calls, browser diagnostics, and stateful components—each technology is demonstrated where it belongs.</p><button class="link-inline" style="border:0;background:none;padding:0" data-action="navigate" data-route="lab">See the technology in action ${icon('arrow',14)}</button></div><div class="skill-chips">${['HTML5 & semantic markup','CSS3 / Grid / Flexbox','Responsive media queries','JavaScript ES6+','jQuery & AJAX','React components','Bootstrap 5','REST APIs','Git-ready source','Chrome DevTools','Error handling','Accessibility basics','Shared demonstration catalog','Order workflows','Image optimization','Performance checks','Node.js'].map(t=>`<span>${t}</span>`).join('')}</div></section><section class="evidence-section"><div class="section-title"><div><span class="eyebrow"><span class="mini-dot"></span>REQUIREMENT → EVIDENCE</span><h2 style="margin-top:11px">Don't take a claim on trust.</h2><p>Here is exactly where to verify the implementation.</p></div><span class="pill outline">LIVE EVIDENCE MAP</span></div><div class="evidence-table-wrap"><table class="evidence-table"><thead><tr><th>TECHNICAL SKILL</th><th>WORKING EVIDENCE</th><th>TRY IT</th></tr></thead><tbody>${[
    ['HTML5 / CSS3 / Design-to-code','Live page built from an SVG handoff with editable CSS tokens','studio'],
    ['Responsive design & media queries','Desktop / tablet / mobile preview and fluid layout rules','studio'],
    ['JavaScript ES6+','Catalog filters, shopping bag, form validation, state persistence','store'],
    ['jQuery / AJAX / Plugins','Debounced JSON search, error state, custom $.fn plugin','lab'],
    ['React components','State-driven project configurator and derived totals','lab'],
    ['Bootstrap 5','Actual responsive grid classes at three breakpoints','lab'],
    ['API & debugging','HTTP responses, intentional 503, validated 422, browser checks','quality'],
    ['eCommerce UX','Products → quick view → persistent cart → sample checkout','store'],
    ['Commerce operations','Admin CRUD, SKU validation, stock management, fulfillment status and order inventory reservation','admin'],
    ['Optimized frontend assets','Small SVG illustrations, lazy loading, no external image service','quality'],
  ].map(([skill,proof,route])=>`<tr><th scope="row">${skill}</th><td>${proof}</td><td><button class="link-inline" data-action="navigate" data-route="${route}">Open ${icon('arrow',13)}</button></td></tr>`).join('')}</tbody></table></div><p class="small muted" style="margin-top:12px">The demo does not claim live CMS integrations or Photoshop authoring; it shows independently verifiable frontend skills.</p></section>
  </main>`;}
  function productCard(p){return `<article class="product-card"><div class="product-image"><img src="${safe(p.image)}" alt="${safe(p.name)} product illustration" loading="lazy" width="800" height="720"><span class="product-badge">${safe(p.tag)}</span><div class="product-actions"><button class="circle-action" data-action="quick" data-id="${safe(p.id)}" aria-label="Quick view ${safe(p.name)}">${icon('eye',18)}</button></div></div><div class="product-info"><span class="product-category">${safe(p.category)}</span><button class="product-name" data-action="quick" data-id="${safe(p.id)}">${safe(p.name)}</button><span class="product-color">${safe(p.color)}</span><div class="product-bottom"><div class="price">${money(p.price)}${p.oldPrice?`<del>${money(p.oldPrice)}</del>`:''}</div><button class="small-add" data-action="add" data-id="${safe(p.id)}" ${p.inventory===0?'disabled aria-disabled="true"':''}>${p.inventory===0?'Sold out':'+ Add to bag'}</button></div></div></article>`;}
  function store(){return `<main id="main" class="container-app page">${pageHead('01 / COMMERCE ENGINEERING','The storefront.','A fully functional shopping experience. Search, filter, inspect, add to bag, and complete a simulated checkout—backed by a real Node API.')}<div class="store-banner"><div style="z-index:1"><span class="eyebrow">MONO / GOODS — A SAMPLE COMMERCE BRAND</span><h2>Considered objects.<br>Everyday better.</h2><p>Discover thoughtfully crafted essentials for your desk, your space, and your routine.</p></div><img src="/assets/speaker.svg" alt="Minimalist speaker illustration"></div><div class="admin-store-teaser"><span>MANAGE THE COLLECTION</span><p>Create a product or process a sample order from the connected back office.</p><button type="button" class="button secondary" data-action="navigate" data-route="admin">Open commerce admin ↗</button></div><section class="store-layout"><div class="section-title"><div><h2 style="font-size:27px">The collection</h2><p>Products retrieved from the live catalog API.</p></div><span class="pill green" id="product-count">${state.products.length||'—'} PRODUCTS</span></div><div class="store-controls"><div class="filter-chips" role="group" aria-label="Filter by category">${CATEGORIES.map(c=>`<button class="filter-chip${state.category===c?' active':''}" data-action="filter" data-category="${c}" aria-pressed="${state.category===c}">${c}</button>`).join('')}</div><div class="store-tools"><label class="search-control">${icon('search',16)} <input id="store-search" type="search" placeholder="Search products" value="${safe(state.query)}" aria-label="Search products" autocomplete="off"></label><select class="select-control" id="store-sort" aria-label="Sort products"><option value="featured"${state.sort==='featured'?' selected':''}>Featured</option><option value="price-asc"${state.sort==='price-asc'?' selected':''}>Price: Low–High</option><option value="price-desc"${state.sort==='price-desc'?' selected':''}>Price: High–Low</option><option value="name"${state.sort==='name'?' selected':''}>Name: A–Z</option></select></div></div><div id="products-grid" class="products-grid" aria-live="polite">${state.products.length?state.products.map(productCard).join(''):'<div class="empty-state"><h3>Loading the collection…</h3><p>Retrieving products from the API.</p></div>'}</div><div class="store-bottom"><span>✓ REAL API FILTERING &nbsp; ✓ PERSISTENT CART &nbsp; ✓ VALIDATED CHECKOUT</span><span>Fictional store · Orders appear in the connected demo admin queue</span></div></section></main>`;}
  function checkoutPage(){
    const items=Object.entries(state.cart).map(([id,qty])=>({product:getProduct(id),qty:Number(qty)})).filter(x=>x.product&&x.qty>0);
    const subtotal=Math.round(items.reduce((sum,{product,qty})=>sum+Math.round(product.price*100)*qty,0))/100;
    const shipping=subtotal>=150?0:12;
    return `<main id="main" class="container-app page checkout-page">
      <div class="checkout-breadcrumb"><button class="link-inline" data-action="navigate" data-route="store">← Back to the storefront</button><span>STORE / CART / SECURE DEMO CHECKOUT</span></div>
      ${pageHead('CUSTOMER EXPERIENCE / 02','Checkout.','Complete a fictional customer transaction and see the same order appear in the business-owner dashboard.')}
      <div class="checkout-security"><b>TEST ENVIRONMENT ONLY</b> Enter only the published test card and fictional customer details. Do not enter real payment, contact or address information. No real charge will occur.</div>
      <div class="checkout-layout"><section class="checkout-main">
        <form id="customer-checkout-form" class="checkout-customer-form">
          <div class="checkout-group"><span class="eyebrow">01 / CUSTOMER</span><h2>Contact information</h2>
            <div class="checkout-fields"><label>Full name (fictional)<input name="customer" required minlength="2" maxlength="80" placeholder="Alex Example" autocomplete="off"/></label><label>Email (fictional)<input name="email" required type="email" placeholder="alex@example.com" autocomplete="off"/></label></div></div>
          <div class="checkout-group"><span class="eyebrow">02 / DELIVERY</span><h2>Shipping information</h2>
            <div class="checkout-fields"><label class="span-2">Street address<input name="address1" required maxlength="120" placeholder="123 Example Lane" autocomplete="off"/></label><label>City<input name="city" required maxlength="60" placeholder="Sample City" autocomplete="off"/></label><label>State<input name="region" required maxlength="40" placeholder="CA" autocomplete="off"/></label><label>ZIP code<input name="postalCode" required maxlength="18" placeholder="90001" autocomplete="off"/></label><label>Country<input value="United States (demo)" readonly aria-readonly="true"/></label></div></div>
          <div class="checkout-group"><span class="eyebrow">03 / PAYMENT SIMULATION</span><h2>Demo card payment</h2>
            <p class="checkout-help">Approved test card: <code>4242 4242 4242 4242</code>. To demonstrate a declined payment, use <code>4000 0000 0000 0002</code>. Expiry <code>12/30</code> · CVC <code>123</code>.</p>
            <div class="checkout-fields"><label class="span-2">Test card number<input name="cardNumber" required inputmode="numeric" maxlength="23" placeholder="4242 4242 4242 4242" autocomplete="off"/></label><label>Test expiration<input name="expiry" required maxlength="5" placeholder="12/30" autocomplete="off"/></label><label>Test CVC<input name="cvc" required type="password" inputmode="numeric" maxlength="3" placeholder="123" autocomplete="off"/></label></div>
            <p class="checkout-no-storage">Card number, expiry and CVC are validated in this browser and are never transmitted to or stored by the server. Only a fictional test token is sent.</p></div>
          <div id="customer-checkout-error" class="checkout-error" role="alert" aria-live="assertive"></div>
          <div class="checkout-form-actions"><button class="button secondary" type="button" data-action="fill-checkout">Fill all fictional test details</button><button class="button" type="submit" ${items.length?'':'disabled'}>Place demo order · ${money(subtotal+shipping)} ${icon('arrow',16)}</button></div>
        </form></section>
        <aside class="checkout-summary"><span class="eyebrow">ORDER SUMMARY</span><h3>Your order</h3>
        ${items.length?items.map(({product,qty})=>`<div class="checkout-product"><img src="${safe(product.image)}" alt=""/><div><b>${safe(product.name)}</b><small>${qty} × ${money(product.price)}</small></div><strong>${money(product.price*qty)}</strong></div>`).join(''):'<p>Your cart is empty. Return to the storefront to add products.</p>'}
        <div class="checkout-totals"><div><span>Subtotal</span><b>${money(subtotal)}</b></div><div><span>Shipping ${subtotal>=150?'(free over $150)':''}</span><b>${money(shipping)}</b></div><div><span>Tax (not calculated in demo)</span><b>$0.00</b></div><div class="grand-total"><span>Demo total</span><b>${money(subtotal+shipping)}</b></div></div>
        <div class="checkout-assurance">✓ Server recalculates prices<br>✓ Inventory reserved on successful order<br>✓ Demo payment approved or declined<br>✓ Admin receives the order</div></aside>
      </div></main>`;
  }
  function confirmationPage(){
    const order=state.lastOrder;
    if(!order)return `<main id="main" class="container-app page confirmation-page"><h1>Order confirmation</h1><p>Order details are shown immediately after the fictional checkout.</p><button class="button" data-action="navigate" data-route="store">Go to storefront</button></main>`;
    return `<main id="main" class="container-app page confirmation-page"><div class="confirmation-card"><span class="eyebrow"><span class="mini-dot"></span> ORDER CONFIRMED / DEMO</span><span class="confirmation-tick">✓</span><h1>Order placed.</h1><p>Thanks, ${safe(order.customer)}. Your fictional payment was approved and the order is ready for processing.</p><div class="confirmation-number">${safe(order.orderId)}</div><div class="confirmation-facts"><div><span>Payment</span><b>Approved — simulation</b></div><div><span>Amount</span><b>${money(order.total)}</b></div><div><span>Fulfillment</span><b>Ready for label</b></div><div><span>Payment reference</span><b>${safe(order.paymentReference)}</b></div></div><p class="small">Nothing was charged or shipped. The same fictional order can now be processed from the admin console, even in another browser.</p><div class="confirmation-actions"><button class="button secondary" data-action="navigate" data-route="store">Continue shopping</button><button class="button" data-action="navigate" data-route="admin">Process in Admin ${icon('arrow',16)}</button></div></div></main>`;
  }
  function studioCSS(){const d=state.studio;return `:root {\n  --accent: ${d.accent};\n  --card-radius: ${d.radius}px;\n  --section-spacing: ${d.spacing}px;\n}\n\n.hero-card {\n  border-radius: var(--card-radius);\n  padding: var(--section-spacing);\n}\n\n.cta-button {\n  background: var(--accent);\n}`;}
  function studio(){const d=state.studio;return `<main id="main" class="container-app page">${pageHead('02 / RESPONSIVE DESIGN','The design studio.','Move beyond static mockups. Adjust design tokens, change viewport widths, inspect generated CSS, and overlay layout guides in real time.')}<div class="studio-layout"><aside class="panel"><div class="panel-head"><h3>${icon('sliders',16)} &nbsp; Design controls</h3><p>These values update the live preview.</p></div><div class="panel-body studio-controls"><div class="control-group"><label>Accent color <span class="control-value" id="accent-value">${d.accent}</span></label><div class="swatches" role="group" aria-label="Accent color">${[['#45634c','Forest'],['#315aa7','Cobalt'],['#b46b4e','Terracotta'],['#684a84','Plum'],['#333333','Charcoal']].map(([hex,label])=>`<button class="swatch${hex===d.accent?' active':''}" style="background:${hex}" data-action="color" data-color="${hex}" aria-label="${label}" aria-pressed="${hex===d.accent}"></button>`).join('')}</div></div><div class="control-group"><label for="radius-slider">Corner radius <span class="control-value" id="radius-value">${d.radius}px</span></label><input class="slider" id="radius-slider" type="range" min="0" max="36" step="2" value="${d.radius}"></div><div class="control-group"><label for="spacing-slider">Section padding <span class="control-value" id="spacing-value">${d.spacing}px</span></label><input class="slider" id="spacing-slider" type="range" min="12" max="48" step="2" value="${d.spacing}"></div><div class="control-group"><label>Viewport simulator</label><div class="device-toggle">${[['desktop','monitor'],['tablet','tablet'],['mobile','mobile']].map(([dev,ico])=>`<button data-action="device" data-device="${dev}" class="${d.device===dev?'active':''}" aria-label="${dev} view" aria-pressed="${d.device===dev}">${icon(ico,16)}<br>${dev}</button>`).join('')}</div></div><div class="control-group" style="margin-bottom:16px"><label class="check-row"><input type="checkbox" id="grid-toggle" ${d.grid?'checked':''}> Overlay 24px layout grid</label></div><button class="button secondary full" data-action="reset-studio">${icon('refresh',14)} Reset design</button></div></aside>
  <section class="studio-main"><div class="studio-toolbar"><div><strong style="font-size:13px">Live composition</strong><span class="pill green" style="margin-left:11px">REAL CSS TOKENS</span><div class="small muted">Reference layout: NORTH / FORM landing section</div></div><div class="interaction-toolbar"><span class="pill outline" id="studio-viewport-label">${d.device.toUpperCase()} VIEW</span><button class="icon-btn" data-action="copy-css">${icon('copy',15)} Copy CSS</button></div></div><div class="studio-view${d.grid?' studio-grid-on':''}" id="studio-view"><div class="studio-viewport ${d.device}" id="studio-viewport"><div class="studio-render" id="studio-render" style="--studio-accent:${d.accent};--studio-radius:${d.radius}px;--studio-space:${d.spacing}px"><div class="studio-nav"><span>NORTH / FORM</span><nav><span>Objects</span><span>Journal</span><span>About</span></nav><span>↗</span></div><div class="studio-hero"><div><span style="color:var(--studio-accent);font-size:9px;font-weight:800;letter-spacing:1px">THE ART OF SIMPLICITY</span><h2>Make room<br>for better<br>thinking.</h2><p>A collection of considered objects<br>for a more intentional everyday.</p><button type="button">Explore the collection ↗</button></div><div class="studio-photo"><img src="/assets/chair.svg" alt="Minimalist chair illustration"></div></div><div style="display:flex;justify-content:space-between;font-size:9px;color:#8e988e;border-top:1px solid #e7eae4;padding-top:14px"><span>NEW SEASON / 2026</span><span>DESIGNED FOR LIVING</span></div></div></div></div><div class="panel"><div class="panel-head" style="display:flex;justify-content:space-between;align-items:center"><div><h3>CSS output</h3><p>Generated from the active design controls.</p></div><span class="pill">EDITABLE TOKENS</span></div><div class="panel-body" style="padding:16px"><pre id="css-output" class="code-pane">${safe(studioCSS())}</pre><div class="spec-row"><span>Layout system</span><b>CSS Grid + Flexbox</b></div><div class="spec-row"><span>Preview breakpoints</span><b>Desktop / Tablet / Mobile</b></div><div class="spec-row"><span>Assets</span><b>Local SVG · scalable</b></div></div></div><div class="panel"><div class="panel-head" style="display:flex;justify-content:space-between;align-items:center"><div><h3>Design handoff</h3><p>Inspect the source artboard and its implementation notes.</p></div><a href="/assets/design-brief.svg" download="pixelproof-design-brief.svg" class="icon-btn">${icon('arrow',14)} Reference SVG</a></div><div class="panel-body" style="padding:15px"><img src="/assets/design-brief.svg" alt="Design reference artboard featuring a sample product landing page and annotated spacing, typography and color specifications" style="border-radius:10px;border:1px solid #e8ece5;width:100%;max-height:220px;object-fit:contain;background:#edf0e9" loading="lazy"><p class="small muted" style="margin:12px 0 0">A purpose-built SVG design reference, used here to demonstrate the design-to-HTML/CSS handoff. Not a Photoshop PSD file.</p></div></div></section></div></main>`;}
  function lab(){return `<main id="main" class="container-app page">${pageHead('03 / INTERACTIVE COMPONENTS','The interaction lab.','A playground of working components and frontend patterns. Open DevTools, inspect the events, and test the edge cases.')}<div class="lab-grid">
  <section class="lab-box"><div class="lab-box-head"><div><h3>Live AJAX search</h3><p>jQuery · debounced requests · real JSON API</p></div><span class="lab-tag">jQuery + AJAX</span></div><div class="lab-content"><label for="jq-search" class="field-label">SEARCH THE PRODUCT API</label><input id="jq-search" class="input-field" type="search" placeholder="Try 'lamp', 'audio', or 'chair'" autocomplete="off"><div id="jq-suggestions" class="results-list" aria-live="polite"><div class="empty-state" style="padding:33px 10px"><p style="margin:0">Results appear as you type.</p></div></div><p id="jq-status" class="status-caption">Waiting for a search query…</p><div class="interaction-toolbar"><label class="check-row"><input id="simulate-error" type="checkbox"> Simulate 503 network error</label><button class="icon-btn" data-action="retry-ajax">${icon('refresh',13)} Retry</button></div></div></section>
  <section class="lab-box"><div class="lab-box-head"><div><h3>React configurator</h3><p>Stateful rendering · derived totals · component logic</p></div><span class="lab-tag">REACT</span></div><div class="lab-content"><div id="react-root" aria-live="polite"><p>Loading React component…</p></div></div></section>
  <section class="lab-box"><div class="lab-box-head"><div><h3>Form validation</h3><p>Semantic HTML5 · accessible feedback · vanilla JS</p></div><span class="lab-tag">HTML5 + ES6</span></div><div class="lab-content"><form id="contact-demo" novalidate><div class="form-row"><label class="field-label" for="name-demo">FULL NAME</label><input id="name-demo" name="name" class="input-field" autocomplete="name" placeholder="Alex Developer" required minlength="2"><span class="form-error" id="name-error" role="alert"></span></div><div class="form-row"><label class="field-label" for="email-demo">EMAIL ADDRESS</label><input id="email-demo" name="email" class="input-field" type="email" autocomplete="email" placeholder="alex@example.com" required><span class="form-error" id="email-error" role="alert"></span></div><div class="form-row"><label class="field-label" for="topic-demo">TOPIC</label><select class="input-field" id="topic-demo" name="topic" required><option value="">Select a topic</option><option value="design">Design implementation</option><option value="development">Frontend development</option><option value="testing">Quality & testing</option></select><span class="form-error" id="topic-error" role="alert"></span></div><button type="submit" class="button full">Validate sample form ${icon('arrow',14)}</button><div id="form-feedback"></div></form></div></section>
  <section class="lab-box"><div class="lab-box-head"><div><h3>Accessible disclosure</h3><p>Keyboard interaction · ARIA state · progressive enhancement</p></div><span class="lab-tag">VANILLA JS</span></div><div class="lab-content" id="accordion-lab">${[['Why semantic HTML?','Meaningful elements make interfaces understandable to browsers, screen readers, search engines, and future maintainers.'],['What makes a page responsive?','Fluid units, CSS Grid, Flexbox, media queries, and testing at actual viewport widths—not just scaling down a desktop layout.'],['How do you debug a failed request?','Inspect the Network panel for status, headers, payload, and timing; then verify error handling and user-facing feedback.'],['How is third-party code managed?','Keep library boundaries isolated, validate inputs, and avoid allowing direct DOM manipulation inside React-owned components.']].map(([q,a],i)=>`<div class="accordion-item${i===0?' open':''}"><button class="accordion-trigger" aria-expanded="${i===0?'true':'false'}" data-action="accordion"><span style="transform:none">${q}</span><span style="font-size:19px">${i===0?'−':'+'}</span></button><div class="accordion-panel" ${i===0?'style="display:block"':''}>${a}</div></div>`).join('')}</div></section>
  <section class="lab-box wide"><div class="lab-box-head"><div><h3>Custom jQuery plugin</h3><p>A reusable character-budget widget extending $.fn with configuration, progressive states, and an accessible counter.</p></div><span class="lab-tag">PLUGIN DEVELOPMENT</span></div><div class="lab-content"><label class="field-label" for="plugin-message">WRITE A SHORT PRODUCT DESCRIPTION</label><textarea class="input-field" id="plugin-message" rows="3" maxlength="160" placeholder="A timeless object designed for the everyday…"></textarea><div style="display:flex;justify-content:space-between;align-items:center;margin-top:8px"><span class="small muted">Try typing toward the 160-character limit.</span><span id="plugin-counter" class="pill green" aria-live="polite">0 / 160</span></div><div class="code-pane" style="margin-top:17px;max-height:110px">$('#plugin-message').characterBudget({<br>  max: 160, counter: '#plugin-counter'<br>});</div></div></section>
  <section class="lab-box wide"><div class="lab-box-head"><div><h3>Bootstrap responsive grid</h3><p>Actual Bootstrap 5 grid utilities. Resize the browser to watch columns stack.</p></div><span class="lab-tag">BOOTSTRAP 5</span></div><div class="lab-content"><div class="container-fluid px-0"><div class="row g-3"><div class="col-12 col-md-6 col-lg-3"><div class="bs-demo-cell">.col-12<br>.col-md-6<br>.col-lg-3</div></div><div class="col-12 col-md-6 col-lg-3"><div class="bs-demo-cell">.col-12<br>.col-md-6<br>.col-lg-3</div></div><div class="col-12 col-md-6 col-lg-3"><div class="bs-demo-cell">.col-12<br>.col-md-6<br>.col-lg-3</div></div><div class="col-12 col-md-6 col-lg-3"><div class="bs-demo-cell">.col-12<br>.col-md-6<br>.col-lg-3</div></div></div></div><div class="bs-label">1 COLUMN ON MOBILE · 2 ON TABLET · 4 ON DESKTOP</div></div></section>
  </div></main>`;}
  function quality(){return window.PixelProofQA.render();}
  function render(){state.mobileNav=false;root.innerHTML=header()+(state.route==='home'?home():state.route==='store'?store():state.route==='studio'?studio():state.route==='lab'?lab():state.route==='admin'?window.PixelProofAdmin.render():state.route==='checkout'?checkoutPage():state.route==='confirmation'?confirmationPage():quality())+footer()+'<div id="overlay-root"></div>';document.title=`${state.route==='home'?'PixelProof':(navNames.find(r=>r[0]===state.route)?.[1]||(state.route==='checkout'?'Checkout':'Order confirmed'))+' · PixelProof'} — Interactive frontend engineering`;if(state.route==='store')fetchProducts();if(state.route==='lab')initLab();if(state.route==='quality')window.PixelProofQA.mount();if(state.route==='admin')window.PixelProofAdmin.mount();if(state.route==='checkout'&&!state.catalogLoaded)ensureCatalog().then(()=>{if(state.route==='checkout')render();}).catch(()=>toast('Could not load products',true));renderOverlay();}
  function setRoute(){const route=(location.hash.match(/^#\/(\w+)/)||[])[1]||'home';state.route=routes.includes(route)?route:'home';render();window.scrollTo({top:0,behavior:'instant'});}
  function go(route){if(location.hash===`#/${route}`){state.route=route;render();window.scrollTo(0,0);}else location.hash=`#/${route}`;}
  async function ensureCatalog(){if(state.catalogLoaded)return;if(!catalogPromise)catalogPromise=fetch('/api/products').then(async r=>{if(!r.ok)throw Error(`Catalog HTTP ${r.status}`);const data=await r.json();state.catalog=data.products;state.catalogLoaded=true;}).finally(()=>{catalogPromise=null;});return catalogPromise;}
  async function fetchProducts(){if(state.route!=='store')return;if(storeAbort)storeAbort.abort();storeAbort=new AbortController();const grid=document.querySelector('#products-grid');if(grid)grid.setAttribute('aria-busy','true');const query=new URLSearchParams({q:state.query,category:state.category,sort:state.sort});try{const res=await fetch(`/api/products?${query}`,{signal:storeAbort.signal});if(!res.ok)throw new Error(`HTTP ${res.status}`);const data=await res.json();state.products=data.products;if(state.category==='All'&&!state.query)state.catalog=data.products;state.catalogLoaded=true;const el=document.querySelector('#products-grid');if(!el||state.route!=='store')return;el.innerHTML=state.products.length?state.products.map(productCard).join(''):`<div class="empty-state"><h3>No matching products.</h3><p>Try a different category or search term.</p><button class="button secondary" data-action="clear-search">Clear search</button></div>`;el.setAttribute('aria-busy','false');document.querySelector('#product-count').textContent=`${data.total} PRODUCTS`;}catch(e){if(e.name==='AbortError')return;if(grid){grid.innerHTML='<div class="empty-state"><h3>Could not load products.</h3><p>Check the API connection and try again.</p><button class="button secondary" data-action="reload-products">Retry catalog request</button></div>';grid.setAttribute('aria-busy','false');}toast('Catalog request failed',true);}}
  const getProduct = id => state.catalog.find(p=>p.id===id) || state.products.find(p=>p.id===id);
  function updateCartHeader(){document.querySelectorAll('.count-bubble').forEach(el=>el.textContent=cartCount());}
  function add(id){const p=getProduct(id);if(!p)return;const current=Number(state.cart[id]||0);if(current>=Math.min(10,p.inventory)){toast('Maximum quantity reached',true);return;}state.cart[id]=current+1;storeCart();updateCartHeader();toast(`${p.name} added to your bag`);if(state.overlay==='cart')renderOverlay();}
  function changeQty(id,delta){const p=getProduct(id);if(!p)return;const count=Number(state.cart[id]||0)+delta;if(count<=0)delete state.cart[id];else state.cart[id]=Math.min(count,p.inventory,10);storeCart();updateCartHeader();renderOverlay();}
  function openOverlay(type,id){focusReturn=document.activeElement;state.overlay=type;state.quickId=id||null;renderOverlay();document.body.style.overflow='hidden';const close=document.querySelector('.modal-close');if(close)close.focus();}
  function closeOverlay(){state.overlay=null;const target=document.querySelector('#overlay-root');if(target)target.innerHTML='';document.body.style.overflow='';focusReturn?.focus?.();}
  function renderOverlay(){const target=document.querySelector('#overlay-root');if(!target)return;if(!state.overlay){target.innerHTML='';return;}
    if(state.overlay==='quick'){
      const p=getProduct(state.quickId);if(!p)return;
      const available=Math.max(0,Number(p.inventory)||0);
      const related=state.catalog.filter(item=>item.id!==p.id).sort((a,b)=>Number(b.category===p.category)-Number(a.category===p.category)).slice(0,4);
      const shipping=p.price>=150?0:12;
      target.innerHTML=`<div class="overlay" data-action="backdrop"><div class="modal amazon-product-modal" role="dialog" aria-modal="true" aria-label="${safe(p.name)} product details">
        <button class="modal-close" data-action="close" aria-label="Close quick view">${icon('close',18)}</button>
        <div class="amazon-breadcrumb">MONO / GOODS <span>›</span> ${safe(p.category)} <span>›</span> ${safe(p.name)}</div>
        <div class="amazon-product-main">
          <section class="amazon-gallery" aria-label="Product photo"><div class="amazon-image-frame"><img src="${safe(p.image)}" alt="${safe(p.name)} illustration"></div><div class="amazon-gallery-caption">Illustrative product image · Demo catalog</div></section>
          <section class="amazon-product-information">
            <span class="amazon-store-name">Visit the MONO / GOODS demo store</span>
            <h2>${safe(p.name)}</h2>
            <div class="amazon-rating"><span class="amazon-stars" aria-label="Fictional rating four point eight out of five">★★★★★</span><span>4.8 out of 5</span><a href="#amazon-reviews" data-action="jump-reviews">24 sample ratings</a></div>
            <div class="amazon-hr"></div>
            ${p.oldPrice?`<div class="amazon-old-price">List price <del>${money(p.oldPrice)}</del></div>`:''}
            <div class="amazon-main-price">${money(p.price)}</div><div class="amazon-tax-note">Sample price · No actual purchases</div>
            <div class="amazon-hr"></div>
            <p class="amazon-description">${safe(p.description)}</p>
            <h3>About this item</h3>
            <ul class="amazon-feature-list"><li>Designed as part of the MONO / GOODS example collection</li><li>Finish: ${safe(p.color)}</li><li>Category: ${safe(p.category)}</li><li>Catalog-backed stock and price displayed above</li></ul>
            <h3>Product information</h3>
            <table class="amazon-spec-table"><tbody><tr><th>Product name</th><td>${safe(p.name)}</td></tr><tr><th>Finish / color</th><td>${safe(p.color)}</td></tr><tr><th>Category</th><td>${safe(p.category)}</td></tr><tr><th>Product ID</th><td>${safe(p.id)}</td></tr><tr><th>Inventory</th><td>${available} units (demo)</td></tr></tbody></table>
            <p class="amazon-spec-note">Dimensions, weight, compatibility and manufacturer claims are not available in the catalog.</p>
          </section>
          <aside class="amazon-buy-box" aria-label="Purchase options">
            <div class="amazon-buy-price">${money(p.price)}</div>
            <p><strong>${shipping===0?'FREE demo delivery':money(shipping)+' sample shipping'}</strong><br>Illustrative delivery in 3–5 business days</p>
            <div class="amazon-buy-stock ${available?'':'soldout'}">${available?'In stock':'Currently unavailable'}</div><small>${available} units available · sample inventory</small>
            <div class="amazon-buy-actions"><button class="amazon-cart-button" data-action="add" data-id="${safe(p.id)}" ${available?'':'disabled'}>${icon('bag',16)} Add to bag</button><button class="amazon-buy-button" data-action="quick-buy" data-id="${safe(p.id)}" ${available?'':'disabled'}>Buy now · Demo checkout</button></div>
            <div class="amazon-buy-meta"><div><span>Ships from</span><b>Sample store</b></div><div><span>Sold by</span><b>MONO / GOODS demo</b></div><div><span>Returns</span><b>30-day sample policy</b></div><div><span>Payment</span><b>Fictional test only</b></div></div>
            <p class="amazon-buyer-note">No real payment, shipping, warranty or delivery service is offered.</p>
          </aside>
        </div>
        <section class="amazon-below"><div><h3>Product description</h3><p>${safe(p.description)}</p><p>Illustrative product detail experience using the current store catalog.</p></div><div id="amazon-reviews"><h3>Customer reviews <span>(fictional examples)</span></h3><div class="amazon-review"><strong><span>★★★★★</span> Thoughtful design</strong><p>“Simple styling and an attractive finish.”</p><small>Example review, not submitted by a customer</small></div><div class="amazon-review"><strong><span>★★★★☆</span> Good everyday item</strong><p>“Fits a minimal modern setup.”</p><small>Example review, not submitted by a customer</small></div></div></section>
        ${related.length?`<section class="amazon-recommendations"><h3>Products related to this item</h3><div class="amazon-recommendation-grid">${related.map(item=>`<button class="amazon-recommendation" data-action="quick" data-id="${safe(item.id)}"><img src="${safe(item.image)}" alt=""><strong>${safe(item.name)}</strong><span>${money(item.price)}</span></button>`).join('')}</div></section>`:''}
        <footer class="amazon-product-footer">PixelProof demonstration storefront · All customer reviews, fulfillment times, and policies on this page are examples.</footer>
      </div></div>`;
    }
    if(state.overlay==='cart'){const items=Object.entries(state.cart).map(([id,qty])=>({p:getProduct(id),qty:Number(qty)})).filter(x=>x.p&&x.qty>0);const total=items.reduce((s,{p,qty})=>s+p.price*qty,0);const shipping=total>=150?0:12;target.innerHTML=`<div class="overlay drawer-overlay" data-action="backdrop"><aside class="drawer" role="dialog" aria-modal="true" aria-label="Shopping bag"><div class="drawer-head"><h3>Your bag <span class="pill green">${cartCount()} ITEMS</span></h3><button class="modal-close" style="position:static;box-shadow:none;background:#f0f3ef" data-action="close" aria-label="Close shopping bag">${icon('close',18)}</button></div><div class="drawer-body">${items.length?items.map(({p,qty})=>`<div class="cart-item"><img src="${safe(p.image)}" alt="${safe(p.name)}"><div><strong>${safe(p.name)}</strong><small>${safe(p.color)}</small><div class="qty-control"><button data-action="qty" data-id="${safe(p.id)}" data-delta="-1" aria-label="Decrease quantity">−</button><b style="font-size:12px">${qty}</b><button data-action="qty" data-id="${safe(p.id)}" data-delta="1" aria-label="Increase quantity">+</button><strong style="margin-left:auto">${money(p.price*qty)}</strong></div></div></div>`).join(''):`<div class="drawer-empty">${icon('bag',35)}<h3>Your bag is empty</h3><p>Find something you love in the collection.</p><button class="button" data-action="close">Continue exploring ${icon('arrow')}</button></div>`}</div>${items.length?`<div class="drawer-bottom"><div class="checkout-row"><span>Subtotal</span><strong>${money(total)}</strong></div><div class="checkout-row"><span>Shipping ${total>=150?'(free over $150)':''}</span><strong>${money(shipping)}</strong></div><div class="checkout-row" style="border-top:1px solid #e9efe7;padding-top:13px;font-weight:800"><span>Total</span><strong>${money(total+shipping)}</strong></div><button class="button full" type="button" data-action="checkout">Continue to checkout ${icon('arrow',16)}</button><p class="small" style="margin:10px 0">Test checkout with fictional contact and payment details. No actual charges or shipments.</p></div>`:''}</aside></div>`;}}
  function initLab(){if(window.ReactLab)window.ReactLab.mount('react-root');const $=window.jQuery;if(!$)return;const $field=$('#jq-search');$field.off('.pixelproof').on('input.pixelproof',()=>{clearTimeout(searchTimer);searchTimer=setTimeout(requestSuggestions,280);});$('#simulate-error').off('.pixelproof').on('change.pixelproof',()=>{if($field.val().trim())requestSuggestions();});if($.fn.characterBudget)$('#plugin-message').characterBudget({max:160,counter:'#plugin-counter'});}
  function requestSuggestions(){const $=window.jQuery;if(!$)return;const value=$('#jq-search').val().trim();if(jqXHR)jqXHR.abort();if(!value){$('#jq-suggestions').html('<div class="empty-state" style="padding:33px 10px"><p style="margin:0">Results appear as you type.</p></div>');$('#jq-status').text('Waiting for a search query…');return;}$('#jq-status').text('Requesting /api/suggest…');$('#jq-suggestions').html('<p class="small muted">Searching the catalog…</p>');jqXHR=$.ajax({url:'/api/suggest',type:'GET',dataType:'json',data:{q:value,...($('#simulate-error').prop('checked')?{simulate:'error'}:{})},timeout:5000}).done(data=>{$('#jq-suggestions').html(data.suggestions.length?data.suggestions.map(p=>`<div class="result-item"><strong>${safe(p.label)}</strong><span>${safe(p.category)}</span></div>`).join(''):'<div class="empty-state" style="padding:33px 10px"><p style="margin:0">No matching suggestions.</p></div>');$('#jq-status').text(`200 OK · ${data.suggestions.length} results · jQuery $.ajax() · real API`);}).fail((xhr,status)=>{if(status==='abort')return;$('#jq-suggestions').html(`<div class="empty-state" style="padding:33px 10px"><p style="color:#a74c43">Request failed (${safe(xhr.status||'network error')}).</p><p style="margin:0">The UI handles server failures gracefully.</p></div>`);$('#jq-status').text(`ERROR · HTTP ${xhr.status||'offline'} · inspect Network panel`);});}
  function validateDemo(e){e.preventDefault();const fields=[['name-demo','name-error',v=>v.trim().length>=2?'':'Use at least two characters.'],['email-demo','email-error',v=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)?'':'Enter a valid email address.'],['topic-demo','topic-error',v=>v?'':'Select a topic.']];let valid=true;for(const [id,errorId,rule] of fields){const input=document.getElementById(id),err=rule(input.value);document.getElementById(errorId).textContent=err;input.setAttribute('aria-invalid',String(!!err));if(err)valid=false;}const feedback=document.getElementById('form-feedback');feedback.innerHTML=valid?'<div class="form-success">✓ All fields passed validation. This is a client-side demonstration; nothing was submitted.</div>':'';if(!valid)document.querySelector('[aria-invalid="true"]')?.focus();}
  function updateStudio(){const d=state.studio;const renderEl=document.querySelector('#studio-render'),frame=document.querySelector('#studio-viewport');if(!renderEl)return;renderEl.style.setProperty('--studio-accent',d.accent);renderEl.style.setProperty('--studio-radius',`${d.radius}px`);renderEl.style.setProperty('--studio-space',`${d.spacing}px`);frame.className=`studio-viewport ${d.device}`;document.querySelector('#studio-view').classList.toggle('studio-grid-on',d.grid);document.getElementById('accent-value').textContent=d.accent;document.getElementById('radius-value').textContent=`${d.radius}px`;document.getElementById('spacing-value').textContent=`${d.spacing}px`;document.getElementById('css-output').textContent=studioCSS();document.getElementById('studio-viewport-label').textContent=`${d.device.toUpperCase()} VIEW`;document.querySelectorAll('.swatch').forEach(el=>{const active=el.dataset.color===d.accent;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});document.querySelectorAll('[data-device]').forEach(el=>{const active=el.dataset.device===d.device;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});}
  document.addEventListener('click',async e=>{const actionEl=e.target.closest('[data-action]');if(!actionEl)return;const action=actionEl.dataset.action;
    if(action==='backdrop'){if(e.target===actionEl)closeOverlay();return;}
    if(action==='close'){closeOverlay();return;}
    if(action==='navigate'){go(actionEl.dataset.route);return;}
    if(action==='menu'){state.mobileNav=!state.mobileNav;const nav=document.querySelector('.nav-wrap');nav.classList.toggle('open',state.mobileNav);actionEl.setAttribute('aria-expanded',String(state.mobileNav));return;}
    if(action==='cart'){try{await ensureCatalog();openOverlay('cart');}catch{toast('Could not load shopping bag. Try again.',true);}return;}
    if(action==='checkout'){closeOverlay();try{await ensureCatalog();go('checkout');}catch{toast('Could not load the catalog to check out.',true);}return;}
    if(action==='fill-checkout'){const form=document.getElementById('customer-checkout-form');if(form){const values={customer:'Alex Example',email:'alex@example.com',address1:'123 Example Lane',city:'Sample City',region:'CA',postalCode:'90001',cardNumber:'4242 4242 4242 4242',expiry:'12/30',cvc:'123'};for(const [key,value] of Object.entries(values))form.elements.namedItem(key).value=value;toast('Fictional test details filled in');}return;}

    if(action==='quick'){openOverlay('quick',actionEl.dataset.id);return;}
    if(action==='jump-reviews'){e.preventDefault();document.getElementById('amazon-reviews')?.scrollIntoView({behavior:'smooth',block:'start'});return;}
    if(action==='quick-buy'){add(actionEl.dataset.id);closeOverlay();try{await ensureCatalog();go('checkout');}catch{toast('Checkout unavailable. Your bag was saved.',true);}return;}
    if(action==='add'){add(actionEl.dataset.id);return;}
    if(action==='qty'){changeQty(actionEl.dataset.id,Number(actionEl.dataset.delta));return;}
    if(action==='filter'){state.category=actionEl.dataset.category;document.querySelectorAll('.filter-chip').forEach(el=>{const active=el.dataset.category===state.category;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});fetchProducts();return;}
    if(action==='clear-search'){state.query='';state.category='All';state.sort='featured';render();return;}
    if(action==='reload-products'){fetchProducts();return;}
    if(action==='color'){state.studio.accent=actionEl.dataset.color;updateStudio();return;}
    if(action==='device'){state.studio.device=actionEl.dataset.device;updateStudio();return;}
    if(action==='reset-studio'){state.studio={accent:'#45634c',radius:16,spacing:24,device:'desktop',grid:false};render();return;}
    if(action==='copy-css'){try{await navigator.clipboard.writeText(studioCSS());toast('CSS copied to clipboard');}catch{toast('Clipboard permission unavailable. Select the CSS text instead.',true);}return;}
    if(action==='retry-ajax'){requestSuggestions();return;}
    if(action==='accordion'){const parent=actionEl.closest('.accordion-item');const open=!parent.classList.contains('open');parent.classList.toggle('open',open);actionEl.setAttribute('aria-expanded',String(open));actionEl.lastElementChild.textContent=open?'−':'+';const panel=parent.querySelector('.accordion-panel');panel.style.display=open?'block':'none';return;}
  });
  document.addEventListener('input',e=>{if(e.target.id==='store-search'){state.query=e.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(fetchProducts,280);}if(e.target.id==='radius-slider'){state.studio.radius=Number(e.target.value);updateStudio();}if(e.target.id==='spacing-slider'){state.studio.spacing=Number(e.target.value);updateStudio();}if(e.target.id==='grid-toggle'){state.studio.grid=e.target.checked;updateStudio();}});
  document.addEventListener('change',e=>{if(e.target.id==='store-sort'){state.sort=e.target.value;fetchProducts();}});
  document.addEventListener('submit',async e=>{
    if(e.target.id==='contact-demo'){validateDemo(e);return;}
    if(e.target.id!=='customer-checkout-form')return;
    e.preventDefault();
    const form=e.target,err=document.getElementById('customer-checkout-error'),btn=form.querySelector('button[type="submit"]');err.textContent='';
    const values=Object.fromEntries(new FormData(form).entries());
    if(!/^[^\s@]{1,64}@(example\.(?:com|net|org)|[a-z0-9-]+\.(?:test|invalid))$/i.test(values.email)){err.textContent='Please use a fictional email such as alex@example.com; real contact information is not accepted.';return;}
    const pan=String(values.cardNumber||'').replace(/\s|-/g,'');
    if(!['4242424242424242','4000000000000002'].includes(pan)||values.expiry!=='12/30'||values.cvc!=='123'){err.textContent='Use only the published demonstration card details: 4242 4242 4242 4242, expiry 12/30, CVC 123.';return;}
    const payload={customer:values.customer,email:values.email,shipping:{address1:values.address1,city:values.city,region:values.region,postalCode:values.postalCode,country:'US'},paymentToken:pan==='4242424242424242'?'demo-visa-4242':'demo-visa-declined',items:Object.entries(state.cart).map(([id,qty])=>({id,qty:Number(qty)}))};
    btn.disabled=true;btn.textContent='Authorizing demo payment…';
    try{const response=await fetch('/api/orders',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const result=await response.json();if(!response.ok)throw Error(result.error||'Payment or inventory validation failed.');state.lastOrder={...result,customer:values.customer};state.cart={};storeCart();updateCartHeader();state.catalog=[];state.catalogLoaded=false;go('confirmation');toast('Fictional order sent to admin for fulfillment');}
    catch(ex){err.textContent=ex.message;btn.disabled=false;btn.textContent='Try demo checkout again';}
  });
  document.addEventListener('keydown',e=>{if(e.key==='Escape'&&state.overlay)closeOverlay();if(e.key==='Tab'&&state.overlay){const overlay=document.querySelector('.overlay');const focusable=[...overlay.querySelectorAll('button:not([disabled]),input:not([disabled]),a[href],select:not([disabled])')].filter(el=>el.getClientRects().length);if(!focusable.length)return;const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
  window.addEventListener('hashchange',()=>{if(jqXHR)jqXHR.abort();setRoute();});
  setRoute();
  if(state.route!=='admin')ensureCatalog().catch(()=>{});
})();
